SELECT SQL_CALC_FOUND_ROWS ROW_NUMBER() OVER (ORDER BY g5f.fa_order ASC) AS row_num, fa_id, fm_id, fa_subject, fa_content, fa_order FROM g5_faq g5f
g5f.fm_id = #{fmId}
AND (g5f.fa_subject LIKE CONCAT('%', #{searchKeyword}, '%') OR g5f.fa_content LIKE CONCAT('%', #{searchKeyword}, '%'))
LIMIT #{pageNo}, #{pageSize}

